// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { curveMidpoint, nearestEdge } from "../../../main/frontend/graph-explorer/edge-hit.ts";

const curve = (start, control, end) => ({ path: "", start, control, end });
const curves = new Map([
  ["straight", curve({ x: 0, y: 0 }, { x: 50, y: 0 }, { x: 100, y: 0 })],
  ["bent", curve({ x: 0, y: 100 }, { x: 50, y: 40 }, { x: 100, y: 100 })],
]);

test("a point within the tolerance of a curve picks it, the closest one when two are near", () => {
  assert.equal(nearestEdge({ x: 50, y: 4 }, curves, 6), "straight");
  assert.equal(nearestEdge({ x: 50, y: 70 }, curves, 6), "bent", "the bent curve's apex is at y = 70");
  assert.equal(nearestEdge({ x: 50, y: 35 }, curves, 6), null);
  assert.equal(nearestEdge({ x: 50, y: 35 }, curves, 40), "bent");
});

test("points beyond the ends of a curve do not pick it", () => {
  assert.equal(nearestEdge({ x: 120, y: 0 }, curves, 6), null);
});

test("the midpoint of a curve is where its label goes when it has none", () => {
  assert.deepEqual(curveMidpoint(curves.get("bent")), { x: 50, y: 70 });
});
